    {v : Fin 3 → ℝ} (hv : v ∈ stdSimplex2) (hfv : f v ∈ stdSimplex2) {j : Fin 3} (hvj : v j = 0)
    (hne : f v ≠ v) : spernerColor f v ≠ j

