    (hadj : ∀ i, (v.1 i : ℤ) - (w.1 i : ℤ) ∈ Set.Icc (-1 : ℤ) 1) :
    dist (subdivCoord k hk v) (subdivCoord k hk w) ≤ Real.sqrt 2 / k

